module alu #(
    parameter ADD = 6'b100000,
    parameter ADDU = 6'b100001,
    parameter SUB = 6'b100010,
    parameter SUBU = 6'b100011,
    parameter AND = 6'b100100,
    parameter OR = 6'b100101,
    parameter XOR = 6'b100110,
    parameter NOR = 6'b100111,
    parameter SLT = 6'b101010,
    parameter SLTU = 6'b101011,
    parameter SLL = 6'b000000,
    parameter SRL = 6'b000010,
    parameter SRA = 6'b000011,
    parameter SLLV = 6'b000100,
    parameter SRLV = 6'b000110,
    parameter SRAV = 6'b000111,
    parameter JR = 6'b001000,
    parameter LUI = 6'b001111
) (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output reg zero,
    output reg carry,
    output reg negative,
    output reg overflow,
    output reg flag
);

always @(*) begin
    reg [31:0] res;
    reg [31:0] sa, sb;
    sa = $signed(a);
    sb = $signed(b);
    zero = 1'b0;
    carry = 1'b0;
    negative = 1'b0;
    overflow = 1'b0;
    flag = 1'b0;

    case (aluc)
        ADD: begin
            res = sa + sb;
            carry = (sa > 0 && sb > 0 && res <= 0) || (sa < 0 && sb < 0 && res >= 0);
            negative = res < 0;
            overflow = (sa > 0 && sb > 0 && res <= 0) || (sa < 0 && sb < 0 && res >= 0);
        end
        ADDU: begin
            res = a + b;
            carry = (a > 0 && b > 0 && res <= 0);
            negative = res < 0;
        end
        SUB: begin
            res = sa - sb;
            carry = (sa < 0 && sb < 0 && res >= 0) || (sa > 0 && sb > 0 && res <= 0);
            negative = res < 0;
            overflow = (sa < 0 && sb < 0 && res >= 0) || (sa > 0 && sb > 0 && res <= 0);
        end
        SUBU: begin
            res = a - b;
            carry = (a < 0 && b < 0 && res >= 0);
            negative = res < 0;
        end
        AND: begin
            res = a & b;
        end
        OR: begin
            res = a | b;
        end
        XOR: begin
            res = a ^ b;
        end
        NOR: begin
            res = ~(a | b);
        end
        SLT: begin
            res = (sa < sb) ? 1 : 0;
            flag = res;
        end
        SLTU: begin
            res = (a < b) ? 1 : 0;
            flag = res;
        end
        SLL: begin
            res = a << b;
        end
        SRL: begin
            res = a >> b;
        end
        SRA: begin
            res = $signed(a) >>> b;
        end
        SLLV: begin
            res = a << b;
        end
        SRLV: begin
            res = a >> b;
        end
        SRAV: begin
            res = $signed(a) >>> b;
        end
        default: begin
            res = 32'b0;
        end
    endcase

    r = res;
    zero = (res == 32'b0);
end

endmodule
